use vstd::prelude::*;

verus! {

/// Pairwise distinct (no duplicates) in a sequence.
spec fn is_pairwise_distinct(s: Seq<i32>) -> bool {
    forall|i: int, j: int|
        0 <= i && i < s.len() && 0 <= j && j < s.len() && i != j ==> s[i] != s[j]
}

/// Spec for filtering elements <= e (order not fixed by the problem).
spec fn le_filter(s: Seq<i32>, e: i32) -> Seq<i32> {
    s.filter(|x: i32| x <= e)
}

pub fn remove_all_greater(v: Vec<i32>, e: i32) -> (out: Vec<i32>)
    requires
        is_pairwise_distinct(v@),
    ensures
        forall|k: int|
            0 <= k && k < out@.len() ==> out@[k] <= e && v@.contains(out@[k]),
        forall|x: i32|
            v@.contains(x) && x <= e ==> out@.contains(x),
        out@.to_multiset() == le_filter(v@, e).to_multiset(),
        is_pairwise_distinct(out@),
{
    let mut out: Vec<i32> = Vec::new();
    let mut i: usize = 0;

    while i < v.len()
        invariant
            0 <= i <= v.len(),
            is_pairwise_distinct(v@),

            // out contains exactly the <=e elements from v[0..i)
            out@.to_multiset() == le_filter(v@.subrange(0, i as int), e).to_multiset(),

            // pairwise distinctness maintained
            is_pairwise_distinct(out@),

            // elements in out are from v and <= e
            forall|k: int|
                0 <= k && k < out@.len() ==> out@[k] <= e && v@.contains(out@[k]),
        decreases v.len() - i,
    {
        let x = v[i];
        if x <= e {
            // show x wasn't already in out, using input distinctness
            assert(!out@.contains(x)) by {
                // If x were in out, then x would be in v[0..i), hence equal to some earlier v[j],
                // contradicting pairwise distinctness of v.
                if out@.contains(x) {
                    assert(le_filter(v@.subrange(0, i as int), e).contains(x));
                    let j = choose|j: int|
                        0 <= j && j < i as int && v@[j] == x;
                    assert(0 <= j && j < v@.len());
                    assert(i as int != j);
                    assert(v@[i as int] == v@[j]);
                    assert(false);
                }
            };
            out.push(x);
        }
        i += 1;
    }

    // extend multiset equality from prefix to full vector
    assert(v@.subrange(0, v.len() as int) == v@);
    assert(le_filter(v@.subrange(0, v.len() as int), e) == le_filter(v@, e));
    assert(out@.to_multiset() == le_filter(v@, e).to_multiset());

    out
}

} // verus!

